import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int p = sc.nextInt();
        int k = sc.nextInt();
        long mod = 1000000007L;

        if (k == 0) {
            System.out.println(powMod(p, p - 1, mod));
        } else if (k == 1) {
            System.out.println(powMod(p, p, mod));
        } else {
            long ord_k = 1;
            long k_pow_ord = k % p;
            while (k_pow_ord != 1) {
                ord_k++;
                k_pow_ord = (k * k_pow_ord) % p;
            }
            long comps = (p - 1L) / ord_k;
            System.out.println(powMod(p, comps, mod));
        }
        sc.close();
    }

    private static long powMod(long base, long exp, long mod) {
        long result = 1;
        long power = base % mod;
        long exponent = exp;
        while (exponent > 0) {
            if ((exponent & 1) == 1) {
                result = (result * power) % mod;
            }
            power = (power * power) % mod;
            exponent >>= 1;
        }
        return result;
    }
}

